namespace help.screenshot;



using org.junit;

using docking;
using docking.widgets.filter;
using docking.widgets.table;
using docking.widgets.table;
using docking.widgets.table.threaded;
using ghidra.program.model.listing;

public class CommentWindowPluginScreenShots : GhidraScreenShotGenerator {

	public CommentWindowPluginScreenShots() : base()
    {
	}

	/* @Test */
	public void testCommentsWindow()
    {

		//create some interesting comments for the image
		createComments(program);

		// open the comments window
		performAction("Comments", "DockingWindows", true);

		// set the filter text for our comments
		ComponentProvider provider = getProvider("Comment Window");
		setFilterText(provider, "My");

		captureIsolatedProviderWindow(provider.GetType(), 440, 260);
	}

	private void setFilterText(ComponentProvider provider, string text) {

		JComponent component = provider.getComponent();
		GTable commentTable = (GTable) findComponentByName(component, "CommentTable");
		ThreadedTableModel<object,object> tableModel = (ThreadedTableModel<object,object>) commentTable.getModel();
		FilterTextField filterField = (FilterTextField) findComponentByName(component,
			GTableFilterPanel.FILTER_TEXTFIELD_NAME);
		setFilterText(filterField, text);
		waitForTableModel(tableModel);
	}

	private void setFilterText(FilterTextField field, string text) {
		runSwing(() => field.setText(text));
		waitForSwing();
	}

	private void createComments(Program prog)
    {

		int id = prog.startTransaction("Test");
		Listing listing = prog.getListing();
		listing.setComment(addr(0x00401006), CommentType.EOL, "My EOL comment");
		listing.setComment(addr(0x0040101b), CommentType.PRE, "My Pre comment");
		listing.setComment(addr(0x0040101c), CommentType.POST, "My Post comment");
		listing.setComment(addr(0x00401020), CommentType.PLATE, "My Plate comment");
		listing.setComment(addr(0x0040100d), CommentType.REPEATABLE, "My Repeatable comment");
		prog.endTransaction(id, true);
		prog.flushEvents();
		waitForSwing();
	}

}
